package org.slavicmyths.polozaudit;
import java.io.*;import java.nio.file.*;import java.lang.management.*;import java.util.*;import jdk.jfr.*;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.level.levelgen.presets.*;import net.minecraft.world.Difficulty;import net.minecraft.world.entity.*;import net.minecraft.world.entity.monster.*;import net.minecraft.world.level.block.Blocks;
import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.event.tick.ServerTickEvent;import org.slavicmyths.poloz.*;
/** Test mod only. Native accepted command-spawn encounter, scripted damage, no production changes. */
@Mod(value="polozaudit",dist=Dist.CLIENT)
@EventBusSubscriber(modid="polozaudit",value=Dist.CLIENT)
public final class PolozProbe {
 static final String[] NAMES={"A_idle","A_32zombies","B_128pillagers","C_poloz","D_poloz_128pillagers","E_expiry"};static final Path OUT=Path.of(System.getProperty("poloz.output"));static PrintWriter events,frames,ticks,observations,combat;static Recording rec;static boolean opened,ready,finished;static volatile int scene=-1,age;static int bootstrap;static long last,pre,interval;static GreatPoloz boss;static int clientScene=-2,lastObservedAge=-20;static boolean shot;static net.minecraft.world.entity.decoration.ArmorStand camera;
 static void init()throws Exception{Files.createDirectories(OUT);events=new PrintWriter(Files.newBufferedWriter(OUT.resolve("events.txt")));frames=new PrintWriter(Files.newBufferedWriter(OUT.resolve("frames.csv")));ticks=new PrintWriter(Files.newBufferedWriter(OUT.resolve("ticks.csv")));observations=new PrintWriter(Files.newBufferedWriter(OUT.resolve("observations.csv")));combat=new PrintWriter(Files.newBufferedWriter(OUT.resolve("combat.csv")));frames.println("scene,age,ms");ticks.println("scene,age,ms,interval_ns,heap,entities,gc_count,gc_ms");observations.println("scene,age,kind,key,created_or_particles,removed_or_channels,alive_or_poolwarnings,lifetime_sum_or_failures");combat.println("scene,age,alive,phase,action,target_player,target_type,hp,event_state,break_queue,convert_queue,player_x,player_y,player_z");PressureObserver.installLogger();rec=new Recording(Configuration.getConfiguration("profile"));rec.setMaxSize(256L*1024*1024);rec.start();}
 @SubscribeEvent public static void client(ClientTickEvent.Post e){var m=Minecraft.getInstance();if(!opened&&m.screen instanceof TitleScreen){opened=true;try{init();}catch(Exception ex){throw new RuntimeException(ex);}m.options.pauseOnLostFocus=false;m.options.renderDistance().set(8);m.options.simulationDistance().set(5);m.options.framerateLimit().set(260);m.options.enableVsync().set(false);m.options.tutorialStep=net.minecraft.client.tutorial.TutorialSteps.NONE;m.options.save();events.println("ACTIVE_OPTIONS window="+m.getWindow().getWidth()+"x"+m.getWindow().getHeight()+" rd8 sim5 vsyncfalse uncapped GPU="+com.mojang.blaze3d.platform.GlUtil.getRenderer());events.flush();m.createWorldOpenFlows().createFreshLevel("PolozPressure-"+System.currentTimeMillis(),new LevelSettings("Poloz pressure",GameType.SURVIVAL,false,Difficulty.NORMAL,true,new GameRules(),WorldDataConfiguration.DEFAULT),new WorldOptions(340015,false,false),r->r.registryOrThrow(Registries.WORLD_PRESET).getHolderOrThrow(WorldPresets.FLAT).value().createWorldDimensions(),m.screen);return;}
  if(m.level==null||!ready||scene<0||scene>=NAMES.length)return;
  if(clientScene!=scene){clientScene=scene;lastObservedAge=-20;shot=false;PressureObserver.reset(NAMES[scene]);if(camera==null){camera=EntityType.ARMOR_STAND.create(m.level);camera.moveTo(0,-58,-28,0,0);camera.xo=camera.getX();camera.yo=camera.getY();camera.zo=camera.getZ();camera.yRotO=0;camera.xRotO=0;}m.setCameraEntity(camera);}
  PressureObserver.age=age;if(age-lastObservedAge>=20){lastObservedAge=age;PressureObserver.snapshot(observations);}
  if(age>=600&&!shot){shot=true;try(var im=Screenshot.takeScreenshot(m.getMainRenderTarget())){im.writeToFile(OUT.resolve(NAMES[scene]+".png"));}catch(Exception ex){throw new RuntimeException(ex);}}
  if(finished){m.stop();}
 }
 @SubscribeEvent public static void before(ServerTickEvent.Pre e){pre=System.nanoTime();if(!ready||boss==null||!boss.isAlive()||age<=300||age%40!=0)return;var p=e.getServer().getPlayerList().getPlayers().getFirst();float hp=boss.getHealth();boolean hit=boss.hurt(p.damageSources().playerAttack(p),100);events.println("HIT "+NAMES[scene]+" age="+age+" accepted="+hit+" hp="+hp+"->"+boss.getHealth());events.flush();}
 @SubscribeEvent public static void after(ServerTickEvent.Post e){if(events==null||finished)return;long n=System.nanoTime();var s=e.getServer();if(s.getPlayerList().getPlayers().isEmpty())return;var p=s.getPlayerList().getPlayers().getFirst();var w=p.serverLevel();if(!ready){if(++bootstrap<100)return;ready=true;w.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,s);w.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,s);w.setDayTime(18000);scene=0;setup(w,p);return;}age++;
  if(!p.isAlive()||p.getY()<w.getMinBuildHeight()){events.println("INVALID_FIXTURE player_dead_or_void");finish();return;}
  if(boss!=null)combat.println(NAMES[scene]+","+age+","+boss.isAlive()+","+boss.phase()+","+boss.action()+","+(boss.getTarget()==p)+","+(boss.getTarget()==null?"none":BuiltInRegistries.ENTITY_TYPE.getKey(boss.getTarget().getType()))+","+boss.getHealth()+","+PolozEvent.get(w).state+","+boss.impact.breakSize()+","+boss.impact.conversionSize()+","+p.getX()+","+p.getY()+","+p.getZ());
  if(age>300){var rt=Runtime.getRuntime();long gc=0,gcms=0;for(var b:ManagementFactory.getGarbageCollectorMXBeans()){gc+=b.getCollectionCount();gcms+=b.getCollectionTime();}int entities=0;for(var a:w.getAllEntities())entities++;ticks.println(NAMES[scene]+","+age+","+(n-pre)/1e6+","+(interval==0?0:n-interval)+","+(rt.totalMemory()-rt.freeMemory())+","+entities+","+gc+","+gcms);}interval=n;
  if(age>=(scene==5?1100:2100)){PressureObserver.end(events);events.println("END "+NAMES[scene]+" age="+age+" boss_alive="+(boss!=null&&boss.isAlive())+" event="+PolozEvent.get(w).state+" tickets="+((java.util.Set<?>)PressureObserver.field(PolozEvent.get(w),"tickets")).size());events.flush();ticks.flush();frames.flush();combat.flush();observations.flush();if(++scene>=NAMES.length){events.println("COMPLETE");finish();return;}setup(w,p);}
 }
 static void setup(net.minecraft.server.level.ServerLevel w,net.minecraft.server.level.ServerPlayer p){events.println("SCENE transition repeat=0 time="+System.currentTimeMillis());events.flush();PressureObserver.enabled=false;if(PolozEvent.get(w).running())PolozEvent.get(w).finish(w,false);var old=new ArrayList<Entity>();w.getAllEntities().forEach(a->{if(!(a instanceof net.minecraft.world.entity.player.Player))old.add(a);});old.forEach(Entity::discard);boss=null;age=0;
  // Restore the same original flat terrain in each disposable scene; setup excluded from sampling.
  if(scene<5)for(int x=-48;x<=48;x++)for(int z=-48;z<=48;z++)for(int y=-63;y<=-61;y++)w.setBlock(new BlockPos(x,y,z),y==-61?Blocks.GRASS_BLOCK.defaultBlockState():Blocks.DIRT.defaultBlockState(),2);
  p.teleportTo(w,0,-60,-12,0,0);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.fallDistance=0;p.setInvulnerable(false);p.setHealth(20);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE,100000,4));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,net.minecraft.world.item.ItemStack.EMPTY);
  int count=scene==1?32:scene==2||scene==4?128:0;for(int i=0;i<count;i++){Mob mob=scene==1?EntityType.ZOMBIE.create(w):EntityType.PILLAGER.create(w);mob.moveTo(-12+(i%16)*1.6,-60,-4+(i/16)*1.6,180,0);mob.finalizeSpawn(w,w.getCurrentDifficultyAt(mob.blockPosition()),MobSpawnType.COMMAND,null);mob.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1000);mob.setHealth(1000);w.addFreshEntity(mob);mob.setTarget(p);}
  if(scene==3||scene==4){boss=PolozContent.BOSS.get().create(w);boss.moveTo(0,-60,4,180,0);boss.initializeBody();if(!w.addFreshEntity(boss))throw new IllegalStateException("Rejected boss");boss.setTarget(p);var d=PolozEvent.get(w);d.boss=boss.getUUID();d.event=UUID.randomUUID();d.spawn=boss.blockPosition();d.state=PolozEvent.State.ACTIVE;d.elapsed=180;d.setDirty();}
  events.println("SCENE "+NAMES[scene]+" repeat=0 time="+System.currentTimeMillis()+" native_mobs="+count+" accepted_command_encounter="+(boss!=null));events.flush();
 }
 static void finish(){if(finished)return;finished=true;events.flush();frames.flush();ticks.flush();combat.flush();observations.flush();try{rec.stop();rec.dump(OUT.resolve("profile.jfr"));rec.close();}catch(Exception ex){throw new RuntimeException(ex);}Minecraft.getInstance().execute(()->Minecraft.getInstance().stop());}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post e){long n=System.nanoTime();if(ready&&scene>=0&&scene<NAMES.length&&age>300&&!finished)frames.println(NAMES[scene]+","+age+","+(last==0?0:(n-last)/1e6));last=n;}
}
